"""Typed model definitions shared by the offline compiler.

The original toolkit type classes are retained in :mod:`eywa.ast` for
compatibility, but the campaign compiler uses these small immutable-ish nodes.
They deliberately distinguish *declaration* names (enums, structs and aliases)
from the primitive and structural definitions, because only declaration names
appear in a plan's ``types`` list.
"""


class Type:
    __slots__ = ()


class VoidType(Type):
    __slots__ = ()


class BoolType(Type):
    __slots__ = ()


class CharType(Type):
    __slots__ = ()


class IntType(Type):
    __slots__ = ("bits",)

    def __init__(self, bits):
        self.bits = bits


class StringType(Type):
    __slots__ = ("maxsize",)

    def __init__(self, maxsize):
        self.maxsize = maxsize


class EnumType(Type):
    __slots__ = ("name", "values")

    def __init__(self, name, values):
        self.name = name
        self.values = tuple(values)


class ArrayType(Type):
    __slots__ = ("element", "size")

    def __init__(self, element, size):
        self.element = element
        self.size = size


class StructType(Type):
    __slots__ = ("name", "fields", "field_map")

    def __init__(self, name, fields):
        self.name = name
        self.fields = tuple(fields)
        self.field_map = {field_name: field_type
                          for field_name, field_type in self.fields}


class AliasType(Type):
    __slots__ = ("name", "target")

    def __init__(self, name, target):
        self.name = name
        self.target = target


BOOL = BoolType()
CHAR = CharType()
VOID = VoidType()


def underlying(type_node):
    """Look through alias declarations (which are transparent to values)."""
    while isinstance(type_node, AliasType):
        type_node = type_node.target
    return type_node


class TypeSystem:
    """Lazily resolves named type definitions, including forward references."""

    __slots__ = ("definitions", "cache", "_building")

    def __init__(self, definitions):
        self.definitions = {definition["name"]: definition
                            for definition in definitions}
        self.cache = {}
        self._building = set()

    def get(self, name):
        if name in self.cache:
            return self.cache[name]
        if name in self._building:
            # Campaign schemas guarantee an acyclic type graph.  This check is
            # only a defensive guard for malformed development inputs.
            raise ValueError("cyclic type definition")
        self._building.add(name)
        definition = self.definitions[name]
        kind = definition["kind"]
        if kind == "void":
            node = VOID
        elif kind == "bool":
            node = BOOL
        elif kind == "char":
            node = CHAR
        elif kind == "int":
            node = IntType(definition["bits"])
        elif kind == "string":
            node = StringType(definition["maxsize"])
        elif kind == "enum":
            node = EnumType(name, definition["values"])
        elif kind == "array":
            node = ArrayType(self.get(definition["element"]),
                             definition["size"])
        elif kind == "struct":
            fields = tuple((field_name, self.get(field_type))
                           for field_name, field_type in definition["fields"])
            node = StructType(name, fields)
        elif kind == "alias":
            node = AliasType(name, self.get(definition["target"]))
        else:  # pragma: no cover - out-of-domain configurations are not required
            raise ValueError("unknown type kind")
        self._building.remove(name)
        self.cache[name] = node
        return node


def int_width(bits):
    """The smallest of 1, 2, 4, or 8 bytes that holds ``bits`` bits."""
    if bits <= 8:
        return 1
    if bits <= 16:
        return 2
    if bits <= 32:
        return 4
    return 8
